def check_lookup(doc, secs, seen):
    """CHECK 4 (M356): the newest section's LOOKUP line must be substantive and machine-verifiable."""
    fails = []
    if not secs:
        return fails
    sid = secs[-1]
    start = doc.rfind("### " + sid)
    body = doc[start:] if start >= 0 else ""
    look = None
    for ln in body.split("\n"):
        if ln.strip().startswith("LOOKUP:"):
            look = ln.strip()
            break
    if look is None:
        fails.append("newest section %s has no LOOKUP: line" % sid)
        return fails
    m = re.match(r"LOOKUP:\s*(.+?)\s*->\s*(\S+)\s*(.*)$", look)
    if not m:
        fails.append("newest LOOKUP line malformed (must be 'LOOKUP: terms -> target [tag]'): %s" % look[:140])
        return fails
    terms, target, rest = m.group(1), m.group(2), m.group(3).strip()
    hist = doc[:start]
    if target.lower() == "none":
        hits = []
        for t in re.split(r"[,，;；/|]", terms):
            t = t.strip()
            if len(t) < 3:
                continue
            c = hist.count(t)
            if c > 0:
                hits.append("%s x%d" % (t, c))
        if hits:
            fails.append("newest LOOKUP claims 'none' but history hits: %s" % ", ".join(hits[:6]))
        elif "[reason" not in rest.lower():
            fails.append("newest LOOKUP '-> none' must carry '[reason: ...]'")
    else:
        mm = re.match(r"§?(18\.\d+[a-z]?)", target)
        if not mm:
            fails.append("newest LOOKUP target is not a section id nor 'none': %s" % target)
        else:
            if mm.group(1) not in seen:
                fails.append("newest LOOKUP target section missing in doc: %s" % mm.group(1))
            if not re.search(r"\[(relevant|contradicted|partial|none)\b", rest, re.I):
                fails.append("newest LOOKUP target must carry [relevant|contradicted|partial|none]")
            if re.search(r"\[contradicted\b", rest, re.I) and not re.search(r"(explain|because|why|因为|原因)", rest, re.I):
                fails.append("newest LOOKUP [contradicted] requires an explanation (explain:/because:)")
    return fails


def main():
    quiet = "--quiet" in sys.argv
    if not os.path.exists(DOC):
        print("KB_AUDIT_FAIL (missing master doc)")
        return 2
    doc = io.open(DOC, encoding="utf-8", errors="replace").read()
    fail = []

    # 1) sections exist
    secs = re.findall(r"^### (18\.\d+[a-z]?)", doc, re.M)
    if not secs:
        fail.append("no ### 18.x sections in master doc")
    seen = set()
    dups = []
    for s in secs:
        if s in seen:
            dups.append(s)
        seen.add(s)
    # NOTE: historical duplicate section ids exist in the master doc (pre-M100 history). They are tolerated
    # (reported only, not a failure) because the canonical ledger and anchors are what matter.
    if dups and not quiet:
        print("note: duplicate section ids (tolerated): %s" % ",".join(dups[:5]))

    # 2) ledger milestone rows reference existing sections
    rows = re.findall(r"^\| (M\d+) \|([^\n]*)$", doc, re.M)
    if len(rows) < 5:
        fail.append("milestone rows too few: %d" % len(rows))
    for mid, line in rows:
        ids = re.findall(r"(18\.\d+[a-z]?)", line)
        if not ids:
            fail.append("%s row has no section id" % mid)
        for sid in ids:
            if sid not in seen:
                fail.append("%s references missing section %s" % (mid, sid))

    # 3) anchors: newest 25 sections must have an anchor row in this file
    own = io.open(SELF, encoding="utf-8", errors="replace").read()
    newest = secs[-25:] if len(secs) >= 25 else secs
    for s in newest:
        if ('("%s"' % s) not in own:
            fail.append("newest section %s has no anchor in kb_audit.py" % s)

    # 4) M356: LOOKUP substance (must name a real section with a relation tag,
    # or 'none' only when the terms truly have zero history hits)
    fail.extend(check_lookup(doc, secs, seen))

    if fail:
        print("KB_AUDIT_FAIL")
        for f in fail[:20]:
            print("  - " + f)
        return 2
    if not quiet:
        print("rows=%d sections=%d anchors=%d" % (len(rows), len(secs), len(ANCHORS)))
    print("KB_AUDIT_PASS sections=%d" % len(secs))
    return 0


if __name__ == "__main__":
    sys.exit(main())
